} from "@/components/ProgressCarousel";
import { Home } from "lucide-react";
import { useMediaQuery } from "usehooks-ts";

// Credit:
// https://www.ui-layouts.com/components/progressive-carousel

export default function VerticalProgressCarousel() {
	const items = [
		{
			icon: <Home />,
			img: "/itjustworks.jpg",
			title: "Bridge",
			desc: "A breathtaking view of a city illuminated by countless lights, showcasing the vibrant and bustling nightlife.",
			sliderName: "bbridge",
		},
		{
			icon: <Home />,
			img: "/itjustworks.jpg",
			title: "Mountains View",
			desc: "A serene lake reflecting the surrounding mountains and trees, creating a mirror-like surface.",
			sliderName: "bmountains",
		},
		{
			icon: <Home />,
			img: "/itjustworks.jpg",
			title: "Autumn",
			desc: "A picturesque path winding through a dense forest adorned with vibrant autumn foliage.",
			sliderName: "bautumn",
		},
		{
			icon: <Home />,
			img: "/itjustworks.jpg",
			title: "Foggy",
			sliderName: "bfoggy",
			desc: "A stunning foggy view over the foresh, with the sun casting a golden glow across the forest. ",
		},
	];
	const isMobile = useMediaQuery("(min-width: 640px)");
	return (
		<ProgressCarousel
			vertical={isMobile ? true : false}
			fastDuration={300}
			duration={4000}
			activeSlider="bbridge"
			className="sm:flex "
		>
			<SliderBtnGroup className="sm:relative absolute bottom-0 lg:w-[28rem] sm:w-96 w-full z-10 sm:flex sm:flex-col grid grid-cols-2 sm:h-[500px] h-fit sm:dark:bg-black sm:bg-white dark:bg-black/80 bg-white/80 backdrop-blur-md overflow-hidden ">
				{items.map((item, index) => (
					<SliderBtn
						key={item?.sliderName + "button"}
						value={item?.sliderName + "button"}
						className="text-left  p-3 sm:border-b border sm:pl-5 sm:pb-0 pb-6 sm:flex-1"
						progressBarClass="left-0 sm:top-0 bottom-0 dark:bg-white bg-black sm:w-3 sm:h-full h-4  before:h-full before:w-4 before:"
					>
						<span className="relative px-4 rounded w-fit dark:bg-blue-500 bg-black text-white mb-2">
							{item.title}
						</span>
						<span className="text-sm font-medium dark:text-slate-200 text-slate-900 line-clamp-2">
							{item.desc}
						</span>
					</SliderBtn>
				))}
			</SliderBtnGroup>
			<SliderContent className="w-full">
				{items.map((item, index) => (
					<SliderWrapper
						className="h-full"
						key={item.sliderName + "wrapper"}
						value={item?.sliderName + "wrapper"}
					>
						<Image
							className=" h-[500px] object-cover"
							src={item.img}
							width={1900}
							height={1080}
							alt={item.desc}
						/>
					</SliderWrapper>
				))}
			</SliderContent>
		</ProgressCarousel>
	);
}

"use client";

import {
	forwardRef,
	useCallback,
	useEffect,
	useImperativeHandle,
	useMemo,
	useRef,
	useState,
} from "react";

import { cn } from "@/lib/utils";
import { DynamicAnimationOptions, motion } from "motion/react";

// Credit:
// https://www.fancycomponents.dev/docs/components/text/vertical-cut-reveal

interface TextProps {
	children: React.ReactNode;
	reverse?: boolean;
	transition?: DynamicAnimationOptions;
	splitBy?: "words" | "characters" | "lines" | string;
	staggerDuration?: number;
	staggerFrom?: "first" | "last" | "center" | "random" | number;
	containerClassName?: string;
	wordLevelClassName?: string;
	elementLevelClassName?: string;
	onClick?: () => void;
	onStart?: () => void;
	onComplete?: () => void;
	autoStart?: boolean; // Whether to start the animation automatically
}

// Ref interface to allow external control of the animation
export interface VerticalCutRevealRef {
	startAnimation: () => void;
	reset: () => void;
}

interface WordObject {
	characters: string[];
	needsSpace: boolean;
}

const VerticalCutReveal = forwardRef<VerticalCutRevealRef, TextProps>(
	(
		{
			children,
			reverse = false,
			transition = {
				type: "spring",
				stiffness: 190,
				damping: 22,
			},
			splitBy = "words",
			staggerDuration = 0.2,
			staggerFrom = "first",
			containerClassName,
			wordLevelClassName,
			elementLevelClassName,
			onClick,
			onStart,
			onComplete,
			autoStart = true,
			...props
		},
		ref
	) => {
		const containerRef = useRef<HTMLSpanElement>(null);
		const text =
			typeof children === "string" ? children : children?.toString() || "";
		const [isAnimating, setIsAnimating] = useState(false);

		// handy function to split text into characters with support for unicode and emojis
		const splitIntoCharacters = (text: string): string[] => {
			if (typeof Intl !== "undefined" && "Segmenter" in Intl) {
				const segmenter = new Intl.Segmenter("en", {
					granularity: "grapheme",
				});
				return Array.from(
					segmenter.segment(text),
					({ segment }) => segment
				);
			}
			// Fallback for browsers that don't support Intl.Segmenter
			return Array.from(text);
		};

		// Split text based on splitBy parameter
		const elements = useMemo(() => {
			const words = text.split(" ");
			if (splitBy === "characters") {
				return words.map((word, i) => ({
					characters: splitIntoCharacters(word),
					needsSpace: i !== words.length - 1,
				}));
			}
			return splitBy === "words"
				? text.split(" ")
				: splitBy === "lines"
					? text.split("\n")
					: text.split(splitBy);
		}, [text, splitBy]);

		// Calculate stagger delays based on staggerFrom
		const getStaggerDelay = useCallback(
			(index: number) => {
				const total =
					splitBy === "characters"
						? elements.reduce(
								(acc, word) =>
									acc +
									(typeof word === "string"
										? 1
										: word.characters.length +
											(word.needsSpace ? 1 : 0)),
								0
							)
						: elements.length;
				if (staggerFrom === "first") return index * staggerDuration;
				if (staggerFrom === "last")
					return (total - 1 - index) * staggerDuration;
				if (staggerFrom === "center") {
					const center = Math.floor(total / 2);
					return Math.abs(center - index) * staggerDuration;
				}
				if (staggerFrom === "random") {
					const randomIndex = Math.floor(Math.random() * total);
					return Math.abs(randomIndex - index) * staggerDuration;
				}
				return Math.abs(staggerFrom - index) * staggerDuration;
			},
			[elements.length, staggerFrom, staggerDuration]
		);

		const startAnimation = useCallback(() => {
			setIsAnimating(true);
			onStart?.();
		}, [onStart]);

		// Expose the startAnimation function via ref
		useImperativeHandle(ref, () => ({
			startAnimation,
			reset: () => setIsAnimating(false),
		}));

		// Auto start animation
		useEffect(() => {
			if (autoStart) {
				startAnimation();
			}
		}, [autoStart]);

		const variants = {
			hidden: { y: reverse ? "-100%" : "100%" },
			visible: (i: number) => ({
				y: 0,
				transition: {
					...transition,
					delay: ((transition?.delay as number) || 0) + getStaggerDelay(i),
				},
			}),
		};

		return (
			<span
				className={cn(
					containerClassName,
					"flex flex-wrap whitespace-pre-wrap",
					splitBy === "lines" && "flex-col"
				)}
				onClick={onClick}
				ref={containerRef}
				{...props}
			>
				<span className="sr-only">{text}</span>

				{(splitBy === "characters"
					? (elements as WordObject[])
					: (elements as string[]).map((el, i) => ({
							characters: [el],
							needsSpace: i !== elements.length - 1,
						}))
				).map((wordObj, wordIndex, array) => {
					const previousCharsCount = array
						.slice(0, wordIndex)
						.reduce((sum, word) => sum + word.characters.length, 0);

					return (
						<span
							key={wordIndex}
							aria-hidden="true"
							className={cn(
								"inline-flex overflow-hidden",
								wordLevelClassName
							)}
						>
							{wordObj.characters.map((char, charIndex) => (
								<span
									className={cn(
										elementLevelClassName,
										"whitespace-pre-wrap relative"
									)}
									key={charIndex}
								>
									<motion.span
										custom={previousCharsCount + charIndex}
										initial="hidden"
										animate={isAnimating ? "visible" : "hidden"}
										variants={variants}
										onAnimationComplete={
											wordIndex === elements.length - 1 &&
											charIndex === wordObj.characters.length - 1
												? onComplete
												: undefined
										}
										className="inline-block"
									>
										{char}
									</motion.span>
								</span>
							))}
							{wordObj.needsSpace && <span> </span>}
						</span>
					);
				})}
			</span>
		);
	}
);

VerticalCutReveal.displayName = "VerticalCutReveal";
export default VerticalCutReveal;

import registry from "@/registry.json";
import { clsx, type ClassValue } from "clsx";
import type { RegistryItem } from "shadcn/registry";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

const components = registry.items as unknown as RegistryItem[];

export const getComponents = (selectedTags: any[] = []): RegistryItem[] => {
	return selectedTags.length
		? components.filter((component) =>
				selectedTags.every(
					(tag) => component.meta?.tags?.includes(tag) ?? false
				)
			)
		: components;
};

export const getComponentsByNames = (names: string[]): RegistryItem[] => {
	const componentsMap = new Map(components.map((comp) => [comp.name, comp]));

	return names
		.map((name) => componentsMap.get(name))
		.filter((comp): comp is RegistryItem => comp !== undefined);
};

export const getAvailableTags = (selectedTags: any[]): any[] => {
	if (!selectedTags.length) return [];

	// Get all components that have all the selected tags
	const matchingComponents = components.filter((component) =>
		selectedTags.every((tag) => component.meta?.tags?.includes(tag) ?? false)
	);

	// Get all unique tags from the matching components
	const availableTags = new Set<any>();
	matchingComponents.forEach((component) => {
		component.meta?.tags?.forEach((tag: any) => {
			if (!selectedTags.includes(tag)) {
				availableTags.add(tag);
			}
		});
	});

	return Array.from(availableTags);
};

export const convertRegistryPaths = (content: string): string => {
	return content
		.replace(/@\/registry\/default\/ui/g, "@/components/ui")
		.replace(/@\/registry\/default\/compositions/g, "@/components")
		.replace(/@\/registry\/default\/hooks/g, "@/hooks")
		.replace(/@\/registry\/default\/lib/g, "@/lib");
};
